<script setup>
import {computed,onBeforeUnmount,onMounted,reactive,ref} from 'vue';
import {ElMessage,ElMessageBox} from 'element-plus';
import {apiClient,currentApiCacheScope} from '../../utils/api.js';
const categories=[{key:'main',label:'主图'},{key:'detail',label:'详情图'},{key:'title',label:'标题'},{key:'tags',label:'标签'},{key:'description',label:'描述'}];
const common={main:[['主图 A · 清晰白底','以参考图中的真实产品为主体，保持外形、颜色、材质和数量。使用干净白色背景、自然阴影，突出产品细节，主体完整可见。不要添加不存在的配件或声明。'],['主图 B · 使用场景','保持真实产品不变，放入符合用途的真实场景。主体清晰突出，背景简洁，不添加未经确认的适配关系或卖点。'],['主图 C · 质感特写','保持产品真实结构与材质，使用细腻光线和简洁构图突出工艺细节。不要改变颜色、比例、品牌标识或包装数量。']],detail:[['详情图 A · 卖点','每张图解释一个已确认的卖点，用局部特写和简洁俄语说明表达，不虚构规格、认证或使用效果。'],['详情图 B · 场景','结合真实产品用途展示一个具体使用场景，与主图保持视觉风格一致，避免误导安装方式。']],title:[['标题 A · 准确搜索','使用自然俄语，先写准确核心品名，再写已确认的适配品牌和型号、材质及数量。避免堆砌关键词、促销词和未经证实的承诺。']],tags:[['标签 A · 精准相关','用俄语生成与产品直接相关的搜索标签，覆盖核心品名、已确认适配、材质和用途。去重，不加入无关品牌或泛化词。']],description:[['描述 A · 清楚可信','用自然俄语说明产品用途、已确认卖点、适配范围、包装内容和注意事项。只使用真实资料，不编造规格或认证。']]};
let disposed=false,loadSequence=0;
const active=ref('main'),keyword=ref(''),rows=ref([]),busy=ref(false),editor=ref(false),current=ref(null),form=reactive({name:'',prompt:''});
const defaults=computed(()=>common[active.value].map(([name,prompt])=>({id:name,name,payload:{prompt},builtin:true})));
const visible=computed(()=>[...defaults.value,...rows.value.filter(r=>r.payload.category===active.value)].filter(r=>`${r.name} ${r.payload.prompt}`.includes(keyword.value.trim())));
async function load(){const seq=++loadSequence,scope=currentApiCacheScope();busy.value=true;try{const result=await apiClient.get('/api/product-workflows/prompts',{noCache:true});if(!disposed&&seq===loadSequence&&scope===currentApiCacheScope())rows.value=result;}catch(e){ElMessage.error(e.message);}finally{busy.value=false;}}
function edit(record){current.value=record?.builtin?null:record||null;form.name=record?.name||'';form.prompt=record?.payload.prompt||'';editor.value=true;}
async function save(){const scope=currentApiCacheScope();if(!form.name.trim()||!form.prompt.trim())return ElMessage.warning('请填写名称和提示词');busy.value=true;try{await apiClient.post('/api/product-workflows/prompts',{...(current.value?{id:current.value.id,revision:current.value.revision}:{}),payload:{name:form.name.trim(),category:active.value,prompt:form.prompt.trim()}});if(disposed||scope!==currentApiCacheScope())return;editor.value=false;await load();}catch(e){ElMessage.error(e.message);}finally{busy.value=false;}}
async function remove(record){const scope=currentApiCacheScope();try{await ElMessageBox.confirm(`删除“${record.name}”？`,'删除提示词',{type:'warning'});if(disposed||scope!==currentApiCacheScope())return;await apiClient.post('/api/product-workflows/prompts',{id:record.id,revision:record.revision,payload:{...record.payload,archived:true}});await load();}catch(e){if(e?.message)ElMessage.error(e.message);}}
async function copy(record){try{await navigator.clipboard.writeText(record.payload.prompt);ElMessage.success('提示词已复制');}catch{ElMessage.warning('复制失败，请打开模板手动复制');}}
function resetScope(){loadSequence++;rows.value=[];editor.value=false;current.value=null;form.name='';form.prompt='';busy.value=false;void load();}
onMounted(()=>{load();window.addEventListener('erp:auth-scope-changed',resetScope);});
onBeforeUnmount(()=>{disposed=true;loadSequence++;window.removeEventListener('erp:auth-scope-changed',resetScope);});
</script>
<template><main class="prompt-library" v-loading="busy"><header><h2>提示词库</h2><el-button type="primary" @click="edit()">新增我的模板</el-button></header><el-tabs v-model="active"><el-tab-pane v-for="category in categories" :key="category.key" :label="category.label" :name="category.key"/></el-tabs><el-input v-model="keyword" clearable placeholder="搜索名称或提示词" class="search"/><div class="cards"><article v-for="record in visible" :key="record.id"><header><h3>{{record.name}}</h3><el-tag size="small">{{record.builtin?'通用模板':'企业模板'}}</el-tag></header><p>{{record.payload.prompt}}</p><footer><el-button @click="copy(record)">复制</el-button><el-button @click="edit(record)">{{record.builtin?'另存为我的模板':'编辑'}}</el-button><el-button v-if="!record.builtin" type="danger" link @click="remove(record)">删除</el-button></footer></article></div><el-empty v-if="!visible.length" description="没有匹配的提示词"/><el-dialog v-model="editor" title="保存提示词模板" width="min(700px,94vw)"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="form.name" maxlength="200"/></el-form-item><el-form-item label="提示词"><el-input v-model="form.prompt" type="textarea" :rows="12"/></el-form-item></el-form><template #footer><el-button @click="editor=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存</el-button></template></el-dialog></main></template>
<style scoped>.prompt-library{padding:20px;max-width:1500px;margin:auto}header,footer{display:flex;align-items:center;gap:12px;justify-content:space-between}h2,h3{margin:0}header{margin-bottom:16px}.search{max-width:450px;margin-bottom:20px}.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:18px}article{border:1px solid var(--el-border-color);border-radius:10px;padding:20px;background:var(--el-bg-color)}p{white-space:pre-wrap;line-height:1.8;min-height:100px;color:var(--el-text-color-regular)}footer{justify-content:flex-start;flex-wrap:wrap}</style>
